script:
# Caso de uso 3 - https://gerardoesquivia.com/animejs/
// npm install animejs
import { animate } from 'animejs';

// Mueve .cuadrado 250px a la derecha con rebote.
animate('.cuadrado', {
  translateX: 250,
  duration: 800,
  ease: 'outBounce',
});

// RepeticiÃ³n en bucle, yendo y viniendo.
animate('.cuadrado', {
  translateX: 250,
  loop: true,
  alternate: true,
});
